CREATE DATABASE IF NOT EXISTS metallurgy_procurement DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER DATABASE metallurgy_procurement CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE metallurgy_procurement;
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(120) NULL UNIQUE, password VARCHAR(100) NOT NULL, real_name VARCHAR(50) NOT NULL, role VARCHAR(20) NOT NULL, status TINYINT NOT NULL DEFAULT 1, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
SET @email_column_exists = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'sys_user' AND column_name = 'email');
SET @email_migration = IF(@email_column_exists = 0, 'ALTER TABLE sys_user ADD COLUMN email VARCHAR(120) NULL UNIQUE AFTER username', 'SELECT 1');
PREPARE email_migration_stmt FROM @email_migration;
EXECUTE email_migration_stmt;
DEALLOCATE PREPARE email_migration_stmt;
CREATE TABLE IF NOT EXISTS material (id BIGINT PRIMARY KEY AUTO_INCREMENT, material_code VARCHAR(50) NOT NULL UNIQUE, material_name VARCHAR(100) NOT NULL, category VARCHAR(30) NOT NULL, unit VARCHAR(20) NOT NULL DEFAULT '吨', main_index_required DECIMAL(5,2), s_max DECIMAL(5,3), p_max DECIMAL(5,3), granularity VARCHAR(50), unit_price DECIMAL(10,2), safety_stock DECIMAL(12,2) NOT NULL DEFAULT 0, remark VARCHAR(255), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS supplier (id BIGINT PRIMARY KEY AUTO_INCREMENT, supplier_code VARCHAR(50) NOT NULL UNIQUE, supplier_name VARCHAR(100) NOT NULL, contact_person VARCHAR(50), phone VARCHAR(30), address VARCHAR(200), main_materials VARCHAR(200), business_license VARCHAR(100), status TINYINT NOT NULL DEFAULT 1, remark VARCHAR(255), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT, plan_code VARCHAR(30) NOT NULL UNIQUE, material_id BIGINT NOT NULL, quantity DECIMAL(12,2) NOT NULL, expect_date DATE, apply_dept VARCHAR(100), reason VARCHAR(200), applicant VARCHAR(50), apply_time DATETIME, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', approver VARCHAR(50), approve_time DATETIME, approve_remark VARCHAR(255), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_order (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_code VARCHAR(30) NOT NULL UNIQUE, plan_id BIGINT, supplier_id BIGINT NOT NULL, material_id BIGINT NOT NULL, quantity DECIMAL(12,2) NOT NULL, unit_price DECIMAL(10,2) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, order_date DATE, expect_arrival_date DATE, received_quantity DECIMAL(12,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'CREATED', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS arrival_inspect (id BIGINT PRIMARY KEY AUTO_INCREMENT, inspect_code VARCHAR(30) NOT NULL UNIQUE, order_id BIGINT NOT NULL, material_id BIGINT NOT NULL, arrival_date DATE, arrival_quantity DECIMAL(12,2) NOT NULL, main_index_actual DECIMAL(5,2), s_actual DECIMAL(5,3), p_actual DECIMAL(5,3), granularity_ok TINYINT NOT NULL DEFAULT 0, result VARCHAR(20), inspector VARCHAR(50), inspect_time DATETIME, remark VARCHAR(255), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inbound (id BIGINT PRIMARY KEY AUTO_INCREMENT, in_code VARCHAR(30) NOT NULL UNIQUE, inspect_id BIGINT NOT NULL, order_id BIGINT NOT NULL, material_id BIGINT NOT NULL, quantity DECIMAL(12,2) NOT NULL, in_time DATETIME, operator VARCHAR(50), remark VARCHAR(255), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory (id BIGINT PRIMARY KEY AUTO_INCREMENT, material_id BIGINT NOT NULL UNIQUE, quantity DECIMAL(12,2) NOT NULL DEFAULT 0, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS outbound (id BIGINT PRIMARY KEY AUTO_INCREMENT, out_code VARCHAR(30) NOT NULL UNIQUE, material_id BIGINT NOT NULL, quantity DECIMAL(12,2) NOT NULL, dept VARCHAR(100), out_time DATETIME, operator VARCHAR(50), remark VARCHAR(255), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
